import React, { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import './History.css';

/* ═══════════════════════════════════════════════════════════
   SEASON DATA
═══════════════════════════════════════════════════════════ */
const SEASONS = [
  {
    id:    'decode',
    year:  '2025',
    game:  'Decode',
    robot: 'Pegasus',
    tag:   'completed',
    label: 'Decode 2025',
    type:  'completed',
    league: 'East Bay League',
    location: 'Dublin, CA',
    division: 'FTC',
    intro:
      'Our rookie season with Pegasus — a precision-built robot powered by OnShape CAD ' +
      'and a Java + Pedro Pathing software stack. Pegasus competed in four East Bay League ' +
      'events, earned a Connect Award at the League Tournament, and set the foundation ' +
      'for everything Team 30473 will build next.',
    stats: [
      { val: '4',      label: 'Events Competed' },
      { val: '20',     label: 'Matches Played'  },
      { val: 'Top 10', label: 'Tournament Rank' },
      { val: '1',      label: 'Award Won'        },
    ],
    award: {
      icon:  '🏆',
      name:  'Connect Award',
      event: 'East Bay League Tournament',
      desc:
        'The FIRST Tech Challenge Connect Award recognizes teams that best exemplify the ' +
        'FIRST mission — inspiring others to pursue STEM through advocacy, partnerships, and ' +
        'outreach. Winning this in our rookie season reflects our commitment to community ' +
        'impact, from founding BASE Robotics to hosting free workshops across the Tri-Valley.',
      outreachStats: [
        { val: '2',    label: 'Nonprofits Founded / Joined' },
        { val: '100+', label: 'Students Reached' },
        { val: '4',    label: 'FTC Teams Assisted' },
      ],
    },
    events: [
      {
        id:        'meet-1',
        name:      'East Bay League — Meet 1',
        shortName: 'Meet 1',
        date:      'Oct 2024',
        venue:     'East Bay Region, CA',
        result:    'Participated',
        status:    'debut',
        isAward:   false,
        detail:
          'Pegasus took the competition field for the very first time. We stress-tested our ' +
          'autonomous routines in a live match environment, validating Pedro Pathing trajectory ' +
          'accuracy and gathering critical performance data to drive our next round of ' +
          'mechanical and software refinements.',
      },
      {
        id:        'meet-2',
        name:      'East Bay League — Meet 2',
        shortName: 'Meet 2',
        date:      'Nov 2024',
        venue:     'East Bay Region, CA',
        result:    'Participated',
        status:    'competed',
        isAward:   false,
        detail:
          'Armed with Match 1 footage and telemetry data, Pegasus returned with targeted ' +
          'hardware updates and refined Pedro Pathing trajectories — improving our autonomous ' +
          'cycle count and tightening driver-to-robot coordination in teleop.',
      },
      {
        id:        'meet-3',
        name:      'East Bay League — Meet 3',
        shortName: 'Meet 3',
        date:      'Dec 2024',
        venue:     'East Bay Region, CA',
        result:    'Participated',
        status:    'competed',
        isAward:   false,
        detail:
          'Our most polished regular-season outing. Pegasus\'s autonomous reliability reached ' +
          'a new high-water mark, with Pinpoint odometry holding sub-2 cm positional accuracy ' +
          'across full-field traversals. Alliance coordination showed measurable improvement ' +
          'heading into the League Tournament.',
      },
      {
        id:        'tournament',
        name:      'East Bay League Tournament',
        shortName: 'Tournament',
        date:      'Jan 2025',
        venue:     'East Bay Region, CA',
        result:    '🏆 Connect Award',
        status:    'award',
        isAward:   true,
        detail:
          'Pegasus delivered its defining performance — 20 successful matches across 4 ' +
          'competitions, driven by Pinpoint odometry and Pedro Pathing for reliable, ' +
          'repeatable autonomous cycles. We were selected as the 1st pick of the 3rd Alliance, ' +
          'contributed consistent teleop scoring through the playoff bracket, and finished ' +
          '4th place overall. The event concluded with Team 30473 taking home the ' +
          'FIRST Tech Challenge Connect Award.',
      },
    ],
  },
  {
    id:    'biobuzz',
    year:  '2026',
    game:  'BIOBUZZ',
    robot: 'TBD',
    tag:   'upcoming',
    label: 'BIOBUZZ 2026',
    type:  'upcoming',
    league: 'East Bay League',
    location: 'Dublin, CA',
    division: 'FTC',
    intro:
      'Our second season. Hardware development is underway and our Pedro Pathing software ' +
      'stack is being refined based on lessons learned with Pegasus. The team is targeting ' +
      'a stronger mechanical package and more aggressive autonomous strategy for BIOBUZZ.',
    stats: [
      { val: '4', label: 'Events Scheduled' },
      { val: '—', label: 'Matches Played'   },
      { val: '—', label: 'Current Rank'     },
      { val: '—', label: 'Awards'           },
    ],
    events: [
      {
        id:        'biobuzz-meet-1',
        name:      'East Bay League — Meet 1',
        shortName: 'Meet 1',
        date:      'Fall 2025',
        venue:     'East Bay Region, CA',
        result:    'TBD',
        status:    'upcoming',
        isAward:   false,
        detail:
          'Our first official match of the BIOBUZZ season. Hardware and software development ' +
          'is underway as we adapt our platform to the new game challenge.',
      },
      {
        id:        'biobuzz-meet-2',
        name:      'East Bay League — Meet 2',
        shortName: 'Meet 2',
        date:      'Winter 2025',
        venue:     'East Bay Region, CA',
        result:    'TBD',
        status:    'upcoming',
        isAward:   false,
